package com.jnapanam.sportszone.training.model;import com.jnapanam.sportszone.identity.model.User;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;
@Entity @Table(name="training_enrollments",uniqueConstraints=@UniqueConstraint(name="uq_training_enrollment",columnNames={"batch_id","user_id"}))public class TrainingEnrollment{@Id private UUID id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="batch_id")private TrainingBatch batch;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="user_id")private User user;@Column(name="participant_name",nullable=false,length=120)private String participantName;@Column(name="participant_age",nullable=false)private int participantAge;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private EnrollmentStatus status;@Column(name="enrolled_at",nullable=false)private Instant enrolledAt;@Column(name="cancelled_at")private Instant cancelledAt;protected TrainingEnrollment(){}public TrainingEnrollment(TrainingBatch b,User u,String n,int a){id=UUID.randomUUID();batch=b;user=u;participantName=n.trim();participantAge=a;status=EnrollmentStatus.ENROLLED;enrolledAt=Instant.now();}public void cancel(){status=EnrollmentStatus.CANCELLED;cancelledAt=Instant.now();}public UUID getId(){return id;}public TrainingBatch getBatch(){return batch;}public User getUser(){return user;}public String getParticipantName(){return participantName;}public int getParticipantAge(){return participantAge;}public EnrollmentStatus getStatus(){return status;}public Instant getEnrolledAt(){return enrolledAt;}public Instant getCancelledAt(){return cancelledAt;}}
